<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $tables = DB::select("SELECT tablename FROM pg_tables WHERE schemaname = \
public\ AND tablename LIKE \category_data_%\"); foreach ($tables as $t) { $tableName = $t->tablename; $items = DB::table($tableName)->where("name_en", "ilike", "%Neelly Star Hotel%")->get(); foreach($items as $item) { echo "Found in $tableName: {$item->name_en}, Prov: {$item->raw_province}, Dist: {$item->raw_district}, DS: {$item->raw_ds}, GN: {$item->raw_gn}\n"; } }
